UPDATE learning_wordbook_entry
SET vocabulary_id = CASE id
    WHEN #{item.id} THEN #{item.vocabularyId}
    END,
    term = CASE id
    WHEN #{item.id} THEN #{item.term}
    END,
    normalized_term = CASE id
    WHEN #{item.id} THEN #{item.normalizedTerm}
    END,
    snapshot_raw_content = CASE id
    WHEN #{item.id} THEN #{item.snapshotRawContent}
    END,
    snapshot_parsed_json = CASE id
    WHEN #{item.id} THEN #{item.snapshotParsedJson}
    END,
    snapshot_tags_json = CASE id
    WHEN #{item.id} THEN #{item.snapshotTagsJson}
    END,
    snapshot_relations_json = CASE id
    WHEN #{item.id} THEN #{item.snapshotRelationsJson}
    END,
    snapshot_provider = CASE id
    WHEN #{item.id} THEN #{item.snapshotProvider}
    END,
    snapshot_model_name = CASE id
    WHEN #{item.id} THEN #{item.snapshotModelName}
    END,
    snapshot_session_id = CASE id
    WHEN #{item.id} THEN #{item.snapshotSessionId}
    END,
    snapshot_time = CASE id
    WHEN #{item.id} THEN #{item.snapshotTime}
    END,
    card_status = CASE id
    WHEN #{item.id} THEN #{item.cardStatus}
    END,
    card_error_message = CASE id
    WHEN #{item.id} THEN #{item.cardErrorMessage}
    END,
    card_generated_time = CASE id
    WHEN #{item.id} THEN #{item.cardGeneratedTime}
    END,
    update_time = #{list[0].updateTime},
    update_by = #{list[0].updateBy},
    version = version + 1
WHERE deleted = 0
  AND id IN
#{item.id}
